from pathlib import Path
import re

path = Path('src/main.jsx')
s = path.read_text(encoding='utf-8')
s = s.replace("{tab==='prestadores'&&<Prestadores data={data} save={save} month={month}/>} ","{tab==='prestadores'&&<Prestadores data={data} save={save} month={month} setMonth={setMonth}/>} ",1)
s = s.replace("{tab==='prestadores'&&<Prestadores data={data} save={save} month={month}/>}","{tab==='prestadores'&&<Prestadores data={data} save={save} month={month} setMonth={setMonth}/>}",1)
provider='''function Prestadores({data,save,month,setMonth}){const list=data.prestadores.filter(x=>x.month===month&&x.ativo!==false),{modal,setModal,close}=useModal();const add=(nome,salario,dias,scs,sp,fluxoPercent)=>{const id=crypto.randomUUID();const months=planningMonths(month,13);const pct=Math.max(0,Math.min(100,Number(fluxoPercent)||50));const rows=months.map(m=>({id:crypto.randomUUID(),prestador_id:id,month:m,nome,salario:Number(salario)||0,dias_uteis:Number(dias)||0,passagem_scs:Number(scs)||0,passagem_sp:Number(sp)||0,fluxo_percent:pct,ativo:true}));save({...data,prestadores:[...data.prestadores,...rows]});close()};const updatePercent=(p,value)=>{const pct=Math.max(0,Math.min(100,Number(value)||0));save({...data,prestadores:data.prestadores.map(x=>x.prestador_id===p.prestador_id&&x.month>=month?{...x,fluxo_percent:pct}:x)});};return <><div className="toolbar"><MonthSelect month={month} setMonth={setMonth} months={data.fluxo.map(x=>x.month)}/><button className="primary" onClick={()=>setModal({type:'prestador'})}>+ Prestador</button></div><Section title="Prestadores de Serviço">{list.length===0&&<p className="empty">Nenhum prestador neste mês.</p>}{list.map(p=>{const total=totalPrestador(p),pct=Number(p.fluxo_percent??50),toFluxo=total*pct/100;return <div className="provider-row" key={p.id}><div><b>{p.nome}</b><small>{p.dias_uteis} dias · Total {BRL(total)}</small></div><div className="provider-flow"><label><span>% Fluxo</span><input type="number" min="0" max="100" step="1" value={pct} onChange={e=>updatePercent(p,e.target.value)}/></label><div><small>Vai para Fluxo</small><strong>{BRL(toFluxo)}</strong></div></div></div>})}</Section>{modal&&<PrestadorModal onClose={close} onSave={add}/>}</>}'''
modal='''function PrestadorModal({onClose,onSave}){const[nome,setNome]=useState(''),[salario,setSalario]=useState(''),[dias,setDias]=useState(''),[scs,setScs]=useState(''),[sp,setSp]=useState(''),[fluxoPercent,setFluxoPercent]=useState('50');return <Modal title="Novo prestador" onClose={onClose} onSave={()=>nome.trim()&&onSave(nome.trim(),salario,dias,scs,sp,fluxoPercent)}><FormField label="Nome"><input autoFocus value={nome} onChange={e=>setNome(e.target.value)} placeholder="Ex.: Maria"/></FormField><div className="form-grid"><FormField label="Salário"><input inputMode="decimal" type="number" min="0" step="0.01" value={salario} onChange={e=>setSalario(e.target.value)}/></FormField><FormField label="Dias úteis"><input inputMode="numeric" type="number" min="0" value={dias} onChange={e=>setDias(e.target.value)}/></FormField><FormField label="Passagem SCS"><input inputMode="decimal" type="number" min="0" step="0.01" value={scs} onChange={e=>setScs(e.target.value)}/></FormField><FormField label="Passagem SP"><input inputMode="decimal" type="number" min="0" step="0.01" value={sp} onChange={e=>setSp(e.target.value)}/></FormField><FormField label="% direcionado ao Fluxo"><input inputMode="numeric" type="number" min="0" max="100" step="1" value={fluxoPercent} onChange={e=>setFluxoPercent(e.target.value)}/></FormField></div><p className="helper">O padrão é 50%. Você pode alterar por prestador.</p></Modal>}'''
s,n=re.subn(r"function Prestadores\(.*?(?=function PrestadorModal)",provider+"\n",s,count=1,flags=re.S)
if n!=1: raise SystemExit('Prestadores function not found')
s,n=re.subn(r"function PrestadorModal\(.*?(?=function Transferencias)",modal+"\n",s,count=1,flags=re.S)
if n!=1: raise SystemExit('PrestadorModal function not found')
transfer='''function Transferencias({data,save,month,setMonth}){const list=data.transferencias.filter(x=>x.month===month&&x.ativo!==false),fluxo=data.fluxo.find(x=>x.month===month)||{},prestadores=data.prestadores.filter(x=>x.month===month&&x.ativo!==false),despesas=data.despesas.filter(x=>x.month===month&&x.ativo!==false),[editing,setEditing]=useState(null),[nome,setNome]=useState(''),[items,setItems]=useState([]),[type,setType]=useState('fluxo'),[key,setKey]=useState('');const options=type==='fluxo'?FLUXO_FIELDS.map(([k,l])=>({key:k,label:l})):type==='prestador'?prestadores.map(p=>({key:p.prestador_id||p.id,label:p.nome})):despesas.map(d=>({key:d.series_id||d.id,label:d.nome}));useEffect(()=>{if(options.length&&!options.some(o=>o.key===key))setKey(options[0].key||'')},[type,month]);const total=calcTransfer({items},fluxo,prestadores,despesas);const openNew=()=>{setEditing('new');setNome('');setItems([]);setType('fluxo');setKey(FLUXO_FIELDS[0]?.[0]||'')};const openEdit=t=>{setEditing(t.id);setNome(t.nome);setItems(t.items||[]);const first=(t.items||[])[0];setType(first?.type==='prestador_fluxo'||first?.type==='prestador_half'?'prestador':first?.type||'fluxo');setKey(first?.key||'')};const addItem=()=>{if(!key||items.some(i=>i.type===type&&(i.key===key)))return;setItems([...items,{type:type==='prestador'?'prestador_fluxo':type,key}])};const removeItem=i=>setItems(items.filter((_,idx)=>idx!==i));const saveTransfer=()=>{if(!nome.trim()||!items.length)return;const id=editing==='new'?crypto.randomUUID():editing;const row={id,series_id:id,month,nome:nome.trim(),items,ativo:true};save({...data,transferencias:editing==='new'?[...data.transferencias,row]:data.transferencias.map(x=>x.id===id?{...x,...row}:x)});setEditing(null)};return <><div className="toolbar"><MonthSelect month={month} setMonth={setMonth} months={data.fluxo.map(x=>x.month)}/><button className="primary" onClick={openNew}>+ Transferência</button></div><Section title="Transferências">{list.length===0&&<p className="empty">Nenhuma transferência neste mês.</p>}{list.map(t=><div className="transfer-row" key={t.id}><div><b>{t.nome}</b><small>{(t.items||[]).length} itens · {BRL(calcTransfer(t,fluxo,prestadores,despesas))}</small></div><button className="ghost" onClick={()=>openEdit(t)}>Editar</button></div>)}</Section>{editing!==null&&<Modal title={editing==='new'?'Nova transferência':'Editar transferência'} onClose={()=>setEditing(null)} onSave={saveTransfer}><FormField label="Nome"><input autoFocus value={nome} onChange={e=>setNome(e.target.value)} placeholder="Ex.: Conta conjunta"/></FormField><div className="form-grid"><FormField label="Origem"><select value={type} onChange={e=>setType(e.target.value)}><option value="fluxo">Fluxo</option><option value="prestador">Prestador</option><option value="despesa">Despesa</option></select></FormField><FormField label="Item"><select value={key} onChange={e=>setKey(e.target.value)}>{options.map(o=><option key={o.key} value={o.key}>{o.label}</option>)}</select></FormField></div><button className="secondary" onClick={addItem}>+ Adicionar item</button><div className="transfer-items">{items.map((item,i)=>{const label=item.type==='fluxo'?(FLUXO_FIELDS.find(([k])=>k===item.key)?.[1]||item.key):item.type.startsWith('prestador')?(prestadores.find(p=>(p.prestador_id||p.id)===item.key)?.nome||'Prestador'):despesas.find(d=>(d.series_id||d.id)===item.key)?.nome||'Despesa';return <div className="transfer-item" key={`${item.type}-${item.key}-${i}`}><span>{label}</span><b>{BRL(calcTransfer({items:[item]},fluxo,prestadores,despesas))}</b><button className="ghost" onClick={()=>removeItem(i)}>×</button></div>})}</div><div className="total">Total da transferência <b>{BRL(total)}</b></div></Modal>}</>}'''
s,n=re.subn(r"function Transferencias\(.*?(?=function Budget)",transfer+"\n",s,count=1,flags=re.S)
if n!=1: raise SystemExit('Transferencias function not found')
path.write_text(s,encoding='utf-8')
print('patched provider Flow percentage UI and transfer composition')
